template.script:
document.addEventListener('DOMContentLoaded', function () {
    const btn = document.getElementById('btn-close-delivery-modal');
    const modalEl = document.getElementById('delivery_modal');
    if (!btn || !modalEl) return;

    btn.addEventListener('click', function () {
        if (window.bootstrap && bootstrap.Modal) {
            bootstrap.Modal.getOrCreateInstance(modalEl).hide();
        } else {
            modalEl.classList.remove('show');
            modalEl.style.display = 'none';
            document.body.classList.remove('modal-open');
            const bd = document.querySelector('.modal-backdrop');
            if (bd) bd.remove();
        }
        // limpiar bandera si estaba activa
        fetch('/dismiss_seller_no_delivery', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: '{}'
        });
    });
});

(function () {

    function hasDeliveryPointsDOM() {
        var citySel = document.getElementById('city_modal_id');
        if (!citySel) {
            return false;
        }
        for (var i = 0; i < citySel.options.length; i++) {
            var opt = citySel.options[i];
            if (opt.value && !isNaN(opt.value)) {
                return true;
            }
        }
        return false;
    }

    function reallyShowModal() {
        var el = document.getElementById('delivery_modal');
        if (!el) return;
        if (window.bootstrap && bootstrap.Modal) {
            bootstrap.Modal.getOrCreateInstance(el, { backdrop: 'static', keyboard: false }).show();
            return;
        }
        el.classList.add('show');
        el.style.display = 'block';
        el.removeAttribute('aria-hidden');
        el.setAttribute('aria-modal', 'true');
        if (!document.querySelector('.modal-backdrop')) {
            var bd = document.createElement('div');
            bd.className = 'modal-backdrop fade show';
            document.body.appendChild(bd);
        }
        document.body.classList.add('modal-open');
    }

    function isEmpty(v) {
        return v === null || v === undefined || v === '' || v === '-1';
    }

    function mustOpenNow() {
        var el = document.getElementById('delivery_modal');
        if (!el) return false;

        if (!hasDeliveryPointsDOM()) {
            return false;
        }

        var st = document.getElementById('state_modal_id');
        var ct = document.getElementById('city_modal_id');

        var stateEmpty = !st || isEmpty(st.value);
        var cityEmpty  = !ct || isEmpty(ct.value);

        return stateEmpty || cityEmpty;
    }

    window.addEventListener('load', function () {
        if (mustOpenNow()) {
            reallyShowModal();
            setTimeout(function () {
                if (mustOpenNow()) {
                    reallyShowModal();
                }
            }, 120);
        }
    });

    document.addEventListener('DOMContentLoaded', function () {
        var form = document.getElementById('form_delivery_modal');
        if (!form) {
            return;
        }

        form.addEventListener('submit', function (e) {
            if (!hasDeliveryPointsDOM()) {
                return;
            }

            var stateSel = document.getElementById('state_modal_id');
            var citySel  = document.getElementById('city_modal_id');

            var stateOk = stateSel && !isEmpty(stateSel.value);
            var cityOk  = citySel && !isEmpty(citySel.value) && !isNaN(citySel.value);

            if (!stateOk || !cityOk) {
                e.preventDefault();
                e.stopPropagation();
                form.classList.add('was-validated');
                reallyShowModal();
                return false;
            }
        }, true);
    });

    document.addEventListener('change', function (ev) {
        if (!ev.target || ev.target.id !== 'state_modal_id') return;
        var stateId = ev.target.value || '';
        var citySel = document.getElementById('city_modal_id');
        if (!citySel) return;

        Array.prototype.forEach.call(citySel.options, function (opt) {
            if (opt.value === '') {
                opt.style.display = '';
                opt.selected = true;
                return;
            }
            var sid = opt.getAttribute('state-id');
            var show = (!stateId) || (sid === stateId);
            opt.style.display = show ? '' : 'none';
            if (!show) opt.selected = false;
        });
        citySel.value = ''; 
    });

})();

div.script:
document.addEventListener('DOMContentLoaded', function () {
    var closeBtn = document.getElementById('btn-close-seller-no-delivery');
    var modalEl  = document.getElementById('seller_no_delivery_modal');

    if (closeBtn && modalEl) {
        closeBtn.addEventListener('click', function () {
            // Revertir ubicación
            fetch('/revert_delivery_change', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({})
            }).then(function () {
                // Cerrar modal y recargar la página donde estaba el usuario
                if (window.bootstrap && bootstrap.Modal) {
                    var m = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
                    m.hide();
                } else {
                    modalEl.classList.remove('show');
                    modalEl.style.display = 'none';
                    var bd = document.querySelector('.modal-backdrop');
                    if (bd) bd.remove();
                }
                // recargar para que se apliquen los valores previos
                window.location.reload();
            }).catch(function () {
                // fallback: recargar igual
                window.location.reload();
            });
        });
    }
});

t.script:
document.addEventListener('DOMContentLoaded', function () {
    if (window.location &&  window.location.pathname.indexOf('/sellers') === 0) {
        return;
    }
    var modalEl = document.getElementById('seller_no_delivery_modal');
    if (!modalEl) return;

    if (window.bootstrap && bootstrap.Modal) {
        var modal = new bootstrap.Modal(modalEl, { backdrop: 'static', keyboard: false });
        modal.show();
    } else {
        modalEl.classList.add('show');
        modalEl.style.display = 'block';
        modalEl.removeAttribute('aria-hidden');
        modalEl.setAttribute('aria-modal', 'true');
        var backdrop = document.createElement('div');
        backdrop.className = 'modal-backdrop fade show';
        document.body.appendChild(backdrop);
    }
});
